import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    try:
        N = int(next(iterator))
        K = int(next(iterator))
    except StopIteration:
        return

    # Count frequency of each jump value
    jump_counts = {}
    for _ in range(K):
        x = int(next(iterator))
        jump_counts[x] = jump_counts.get(x, 0) + 1

    # Array to store the value of seq[i]
    # seq[i] will be the number of times index i was updated
    seq = [0] * N

    # For each unique jump, add its count to all its multiples
    for jump, count in jump_counts.items():
        # Start from 0, step by jump
        for i in range(0, N, jump):
            seq[i] += count

    # Build prefix sum array of seq to answer range sum queries in O(1)
    # prefix_sum[i] = seq[0] + ... + seq[i]
    prefix_sum = [0] * N
    current_sum = 0
    for i in range(N):
        current_sum += seq[i]
        prefix_sum[i] = current_sum

    try:
        Q = int(next(iterator))
    except StopIteration:
        return

    results = []
    for _ in range(Q):
        L = int(next(iterator))
        R = int(next(iterator))

        if L == 0:
            ans = prefix_sum[R]
        else:
            ans = prefix_sum[R] - prefix_sum[L-1]
        results.append(str(ans))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
